impl F32ExtraBackend for Simd128Descriptor {
    #[inline(always)]
    fn f32_as_i32(self, a: v128) -> v128 {
        simd128_call!(self, |a: v128| -> v128 { i32x4_trunc_sat_f32x4(a) })
    }
    #[inline(always)]
    fn f32_round_store_u8(self, a: v128, dest: &mut [u8]) {
        simd128_call!(self, |a: v128, dest: &mut [u8]| {
            let i32s = i32x4_trunc_sat_f32x4(f32x4_nearest(a));
            let i16s = i16x8_narrow_i32x4(i32s, i32s);
            let u8s = u8x16_narrow_i16x8(i16s, i16s);
            *dest.first_chunk_mut::<4>().unwrap() = u32x4_extract_lane::<0>(u8s).to_ne_bytes();
        });
    }
    #[inline(always)]
    fn f32_round_store_u16(self, a: v128, dest: &mut [u16]) {
        simd128_call!(self, |a: v128, dest: &mut [u16]| {
            let i = i32x4_trunc_sat_f32x4(f32x4_nearest(a));
            arch_ops::v128_store64_lane0_u16(
                dest.first_chunk_mut().unwrap(),
                u16x8_narrow_i32x4(i, i),
            );
        });
    }
    #[inline(always)]
    fn f32_load_f16_bits(self, mem: &[u16]) -> v128 {
        generic_ops::load_f16_bits_sw(self, mem).0
    }
    #[inline(always)]
    fn f32_store_f16_bits(self, a: v128, dest: &mut [u16]) {
        generic_ops::store_f16_bits_sw(crate::SimdVec(a, self), dest);
    }
}

